      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <main id="main-content" role="main">
  <div class="page-container">
    <section class="hero animate" role="region" aria-label="Title">
      <h1>The AI Evolution</h1>
      <p>Research breakthroughs, industry adoption, and regulatory response — three parallel tracks that converged after ChatGPT. From AlexNet to frontier models, 2010–2025.</p>
    </section>

    <section class="insights-grid animate delay-1" role="region" aria-label="Key insights">
      <div class="insight-card">
        <div class="ic-accent blue"></div>
        <div class="ic-label">Research → Industry Lag</div>
        <div class="ic-value">2–4 years</div>
        <div class="ic-desc">Transformer (2017) to ChatGPT (2022): 5.4 years from paper to product</div>
      </div>
      <div class="insight-card">
        <div class="ic-accent purple"></div>
        <div class="ic-label">ChatGPT Inflection</div>
        <div class="ic-value">14 months</div>
        <div class="ic-desc">Within 14 months: Biden EO, EU AI Act, Bletchley Declaration</div>
      </div>
      <div class="insight-card">
        <div class="ic-accent amber"></div>
        <div class="ic-label">Regulation Lag</div>
        <div class="ic-value">3–5 years</div>
        <div class="ic-desc">Regulation consistently lags industry by 3–5 years before ChatGPT</div>
      </div>
      <div class="insight-card">
        <div class="ic-accent green"></div>
        <div class="ic-label">Investment Surge</div>
        <div class="ic-value">2x in 2 yrs</div>
        <div class="ic-desc">AI investment doubled from $48B (2022) to $96B (2024)</div>
      </div>
    </section>

    <div class="track-legend animate delay-1">
      <div class="track-legend-item"><div class="track-legend-dot research"></div>Research Breakthroughs</div>
      <div class="track-legend-item"><div class="track-legend-dot industry"></div>Industry Adoption</div>
      <div class="track-legend-item"><div class="track-legend-dot regulation"></div>Regulation & Policy</div>
      <div class="significance-legend">
        <div class="sig-item"><div class="sig-dot critical"></div>Critical</div>
        <div class="sig-item"><div class="sig-dot high"></div>High</div>
        <div class="sig-item"><div class="sig-dot medium"></div>Medium</div>
      </div>
    </div>

    <section class="timeline-section animate delay-2" role="region" aria-label="Multi-track timeline">
      <div class="timeline-svg-container" id="timelineContainer">
        <div class="timeline-tooltip" id="tooltip"></div>
      </div>
    </section>

    <section class="investment-section animate delay-2" role="region" aria-label="AI investment chart">
      <h2>Global Private AI Investment</h2>
      <div role="img" aria-label="Area chart showing global private AI investment from $1.3B in 2010 to $120.5B in 2025">
        <div class="chart-wrap">
          <canvas id="investmentChart" role="img" aria-label="AI investment area chart 2010-2025"></canvas>
        </div>
      </div>
      <div class="sr-only">Investment: 2010: $1.3B, 2011: $1.9B, 2012: $2.5B, 2013: $3.2B, 2014: $5.5B, 2015: $8.5B, 2016: $12.2B, 2017: $18.5B, 2018: $28.4B, 2019: $32.1B, 2020: $36.5B, 2021: $52.8B, 2022: $48.2B, 2023: $67.2B, 2024: $95.8B, 2025: $120.5B</div>
    </section>
  </div>
  </main>

  <script>
    // ===== DATA (defined FIRST so it's available before any function calls) =====
    var researchData = [
      {date: "2012-09", label: "AlexNet wins ImageNet", significance: "high", detail: "CNN achieves 15.3% error rate, 10.8pp better than runner-up. Ignites deep learning revolution."},
      {date: "2014-06", label: "GANs published", significance: "high", detail: "Goodfellow et al. introduce Generative Adversarial Networks."},
      {date: "2014-09", label: "Seq2Seq + Attention", significance: "medium", detail: "Bahdanau attention mechanism enables neural machine translation breakthroughs."},
      {date: "2015-12", label: "ResNet (152 layers)", significance: "medium", detail: "Residual connections enable training very deep networks. Superhuman on ImageNet."},
      {date: "2016-03", label: "AlphaGo defeats Lee Sedol", significance: "critical", detail: "DeepMind's Go AI wins 4-1 against world champion. Global media event."},
      {date: "2017-06", label: "Transformer architecture", significance: "critical", detail: "'Attention Is All You Need' — foundation of all modern LLMs."},
      {date: "2018-06", label: "GPT-1 (117M params)", significance: "medium", detail: "OpenAI demonstrates unsupervised pre-training + fine-tuning paradigm."},
      {date: "2018-10", label: "BERT", significance: "high", detail: "Bidirectional pre-training dominates NLP benchmarks. Google deploys in Search."},
      {date: "2020-05", label: "GPT-3 (175B params)", significance: "critical", detail: "Few-shot learning without fine-tuning. Demonstrates emergence of capabilities at scale."},
      {date: "2021-01", label: "DALL-E & CLIP", significance: "high", detail: "Text-to-image generation and vision-language understanding."},
      {date: "2022-04", label: "PaLM (540B params)", significance: "medium", detail: "Google's large model shows chain-of-thought reasoning capabilities."},
      {date: "2023-03", label: "GPT-4", significance: "critical", detail: "Multimodal LLM passes bar exam (90th percentile), SAT (99th percentile)."},
      {date: "2024-02", label: "Gemini 1.5 (1M context)", significance: "high", detail: "Million-token context window enables new application paradigms."},
      {date: "2024-09", label: "o1 reasoning model", significance: "high", detail: "Chain-of-thought at inference time. PhD-level reasoning on benchmarks."},
      {date: "2025-02", label: "Claude 3.5 / GPT-4.5", significance: "high", detail: "Frontier models achieve near-human performance on most professional tasks."}
    ];

    var industryData = [
      {date: "2011-10", label: "Siri launches", significance: "high", detail: "Apple ships first mainstream voice assistant on iPhone 4S."},
      {date: "2014-11", label: "Amazon Echo / Alexa", significance: "high", detail: "Voice AI enters the home. 100M+ units sold by 2020."},
      {date: "2016-09", label: "Google Translate neural", significance: "medium", detail: "NMT replaces phrase-based MT. Translation quality jumps dramatically."},
      {date: "2018-05", label: "Google Duplex demo", significance: "medium", detail: "AI makes phone calls to book appointments. Raises ethical questions."},
      {date: "2020-06", label: "GPT-3 API launches", significance: "high", detail: "First commercial large language model API. Spawns thousands of AI startups."},
      {date: "2021-06", label: "GitHub Copilot preview", significance: "high", detail: "AI pair programming goes mainstream. 1M+ developers by 2022."},
      {date: "2022-08", label: "Stable Diffusion OSS", significance: "high", detail: "Text-to-image AI becomes freely available. Disrupts creative industries."},
      {date: "2022-11", label: "ChatGPT launches", significance: "critical", detail: "100M users in 2 months — fastest consumer app adoption in history."},
      {date: "2023-02", label: "Microsoft Bing + GPT-4", significance: "high", detail: "AI integrated into search. Triggers Google's 'code red' and Bard launch."},
      {date: "2023-07", label: "Meta releases Llama 2", significance: "high", detail: "Open-source LLM competitive with proprietary models. Democratizes access."},
      {date: "2024-01", label: "AI agents in enterprise", significance: "high", detail: "Salesforce, ServiceNow, SAP ship AI agent products."},
      {date: "2024-05", label: "OpenAI GPT-4o", significance: "medium", detail: "Real-time multimodal interaction. Voice, vision, text unified."},
      {date: "2025-01", label: "AI coding agents mainstream", significance: "high", detail: "Cursor, Claude Code, Copilot Workspace — AI writes majority of new code."}
    ];

    var regulationData = [
      {date: "2016-10", label: "Obama AI report", significance: "medium", detail: "First major US government report on AI policy implications."},
      {date: "2018-04", label: "EU GDPR takes effect", significance: "high", detail: "Includes 'right to explanation' for automated decisions."},
      {date: "2019-04", label: "EU AI Ethics Guidelines", significance: "medium", detail: "'Trustworthy AI' framework. Non-binding."},
      {date: "2020-02", label: "EU AI White Paper", significance: "medium", detail: "Proposes risk-based regulatory framework for AI."},
      {date: "2021-04", label: "EU AI Act proposed", significance: "high", detail: "First comprehensive AI regulation. Risk-based tiers."},
      {date: "2022-10", label: "US AI Bill of Rights", significance: "medium", detail: "White House blueprint for AI rights. Non-binding."},
      {date: "2023-05", label: "EU AI Act agreed", significance: "critical", detail: "European Parliament approves AI Act with generative AI provisions."},
      {date: "2023-07", label: "WH voluntary commitments", significance: "high", detail: "7 leading AI companies sign safety commitments."},
      {date: "2023-10", label: "Biden EO on AI", significance: "critical", detail: "Most significant US AI policy. Safety testing, watermarking, standards."},
      {date: "2023-11", label: "Bletchley Declaration", significance: "high", detail: "28 countries + EU sign AI safety declaration."},
      {date: "2024-03", label: "EU AI Act enacted", significance: "critical", detail: "World's first comprehensive AI law. Compliance 2025-2027."},
      {date: "2024-11", label: "CA SB 1047 signed", significance: "high", detail: "First major US state-level AI safety legislation."},
      {date: "2025-02", label: "EU AI Act enforcement", significance: "high", detail: "First tier of obligations take effect. Banned practices enforced."}
    ];

    var investmentData = [
      {year: 2010, investment: 1.3}, {year: 2011, investment: 1.9}, {year: 2012, investment: 2.5},
      {year: 2013, investment: 3.2}, {year: 2014, investment: 5.5}, {year: 2015, investment: 8.5},
      {year: 2016, investment: 12.2}, {year: 2017, investment: 18.5}, {year: 2018, investment: 28.4},
      {year: 2019, investment: 32.1}, {year: 2020, investment: 36.5}, {year: 2021, investment: 52.8},
      {year: 2022, investment: 48.2}, {year: 2023, investment: 67.2}, {year: 2024, investment: 95.8},
      {year: 2025, investment: 120.5}
    ];

    // ===== STATE =====
    var chartsBuilt = false;
    var dataReady = true; // data is defined above, always ready

    // ===== MENU =====
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // ===== THEME =====
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (chartsBuilt && typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // ===== DOWNLOAD =====
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    // ===== BUILD TIMELINE =====
    function buildTimeline() {
      if (!dataReady) return;
      var container = document.getElementById('timelineContainer');
      if (!container) return;
      var containerWidth = container.clientWidth - 48;
      var margin = {top: 70, right: 50, bottom: 30, left: 120};
      var width = containerWidth - margin.left - margin.right;
      var trackHeight = 110;
      var trackGap = 20;
      var totalTrackH = 3 * trackHeight + 2 * trackGap;
      var height = totalTrackH + margin.top + margin.bottom;

      d3.select('#timelineContainer svg').remove();

      var svg = d3.select('#timelineContainer')
        .append('svg')
        .attr('width', containerWidth)
        .attr('height', height);

      var g = svg.append('g').attr('transform', 'translate(' + margin.left + ',' + margin.top + ')');

      var isDark = document.documentElement.classList.contains('theme-dark');
      var textSec = isDark ? '#999' : '#64748b';
      var textPri = isDark ? '#EDEDED' : '#1a1a1a';
      var borderColor = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)';
      var trackR = isDark ? '#3b82f6' : '#2563eb';
      var trackI = isDark ? '#8b5cf6' : '#7c3aed';
      var trackG = isDark ? '#f59e0b' : '#d97706';
      var redColor = isDark ? '#f43f5e' : '#e11d48';
      var surfaceColor = isDark ? '#141414' : '#FFFFFF';
      var labelColor = isDark ? '#bbb' : '#555';

      var xScale = d3.scaleLinear().domain([2010, 2025.5]).range([0, width]);

      var tracks = [
        {name: 'Research', y: 0, color: trackR, data: researchData},
        {name: 'Industry', y: trackHeight + trackGap, color: trackI, data: industryData},
        {name: 'Regulation', y: 2*(trackHeight + trackGap), color: trackG, data: regulationData}
      ];

      // Year grid lines
      var years = d3.range(2010, 2026);
      g.selectAll('.yr-line').data(years).enter().append('line')
        .attr('x1', function(d){return xScale(d);}).attr('x2', function(d){return xScale(d);})
        .attr('y1', -10).attr('y2', totalTrackH + 10)
        .attr('stroke', borderColor).attr('stroke-width', 1);

      // Year labels at top
      g.selectAll('.yr-lbl').data(years.filter(function(d){return d%2===0||d>=2022;})).enter().append('text')
        .attr('x', function(d){return xScale(d);}).attr('y', -32)
        .attr('text-anchor', 'middle').attr('fill', textSec)
        .attr('font-size', '11px').attr('font-family', 'Inter, sans-serif')
        .text(function(d){return d;});

      // Track backgrounds and labels
      tracks.forEach(function(track) {
        g.append('rect').attr('x', 0).attr('y', track.y).attr('width', width).attr('height', trackHeight)
          .attr('rx', 6).attr('fill', track.color).attr('opacity', 0.05);
        g.append('text').attr('x', -16).attr('y', track.y + trackHeight/2 + 5)
          .attr('text-anchor', 'end').attr('fill', track.color)
          .attr('font-size', '14px').attr('font-weight', '600').attr('font-family', 'Inter, sans-serif')
          .text(track.name);
        g.append('line').attr('x1', 0).attr('x2', width)
          .attr('y1', track.y + trackHeight).attr('y2', track.y + trackHeight)
          .attr('stroke', borderColor);
      });

      // ChatGPT inflection line
      var chatX = xScale(2022 + 10/12);
      g.append('line').attr('x1', chatX).attr('x2', chatX)
        .attr('y1', -55).attr('y2', totalTrackH + 10)
        .attr('stroke', redColor).attr('stroke-width', 2).attr('stroke-dasharray', '8 4').attr('opacity', 0.7);
      g.append('text').attr('x', chatX + 8).attr('y', -42)
        .attr('fill', redColor).attr('font-size', '11px').attr('font-weight', '600')
        .attr('font-family', 'Inter, sans-serif').attr('letter-spacing', '0.04em')
        .text('ChatGPT — Nov 2022');

      // Density shading 2023-2025
      g.append('rect').attr('x', xScale(2023)).attr('y', -10)
        .attr('width', xScale(2025) - xScale(2023)).attr('height', totalTrackH + 20)
        .attr('fill', redColor).attr('opacity', 0.03).attr('rx', 4);

      // Density annotation
      var densityMidX = (xScale(2023) + xScale(2025)) / 2;
      g.append('text').attr('x', densityMidX).attr('y', totalTrackH + 26)
        .attr('text-anchor', 'middle').attr('fill', textSec)
        .attr('font-size', '10px').attr('font-family', 'Inter, sans-serif')
        .attr('font-style', 'italic')
        .text('More milestones in 2023-24 than all of 2010-17');

      // Lag annotation: Transformer → ChatGPT
      var transX = xScale(2017 + 5/12);
      var lagY = -16;
      g.append('defs').append('marker').attr('id', 'arr')
        .attr('viewBox', '0 0 10 10').attr('refX', 10).attr('refY', 5)
        .attr('markerWidth', 6).attr('markerHeight', 6).attr('orient', 'auto')
        .append('path').attr('d', 'M 0 0 L 10 5 L 0 10 z').attr('fill', textSec);
      g.append('line').attr('x1', transX).attr('x2', chatX - 4)
        .attr('y1', lagY).attr('y2', lagY)
        .attr('stroke', textSec).attr('stroke-width', 1).attr('marker-end', 'url(#arr)');
      g.append('text').attr('x', (transX + chatX) / 2).attr('y', lagY - 5)
        .attr('text-anchor', 'middle').attr('fill', textSec)
        .attr('font-size', '10px').attr('font-family', 'Inter, sans-serif')
        .text('5.4 yr research → product lag');

      function parseDate(ds) {
        var p = ds.split('-');
        return parseInt(p[0]) + (parseInt(p[1]) - 1) / 12;
      }

      var sigR = {critical: 10, high: 7, medium: 4.5};
      var tooltip = document.getElementById('tooltip');

      tracks.forEach(function(track) {
        var pts = track.data.map(function(d) {
          return { date: d.date, label: d.label, significance: d.significance, detail: d.detail, xVal: parseDate(d.date), r: sigR[d.significance] || 5 };
        });
        pts.sort(function(a,b){ return a.xVal - b.xVal; });

        // Collision-avoidance y assignment
        var rows = [];
        pts.forEach(function(d) {
          var xp = xScale(d.xVal);
          var row = 0; var placed = false;
          while (!placed) {
            var ok = true;
            for (var i = 0; i < rows.length; i++) {
              if (rows[i].row === row && Math.abs(rows[i].xp - xp) < 70) { ok = false; break; }
            }
            if (ok) { d.row = row; rows.push({row: row, xp: xp}); placed = true; }
            else { row++; }
            if (row > 3) { d.row = 0; rows.push({row: 0, xp: xp}); placed = true; }
          }
        });

        pts.forEach(function(d) {
          var cx = xScale(d.xVal);
          var cy = track.y + 22 + d.row * 28;
          if (cy > track.y + trackHeight - 8) cy = track.y + trackHeight - 8;

          // Critical glow
          if (d.significance === 'critical') {
            g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', d.r + 7)
              .attr('fill', track.color).attr('opacity', 0.12);
          }

          // Dot
          g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', d.r)
            .attr('fill', track.color).attr('stroke', surfaceColor).attr('stroke-width', 2)
            .on('mouseenter', function(event) {
              var sc = {critical: redColor, high: track.color, medium: textSec};
              var sb = {critical: isDark?'rgba(244,63,94,0.15)':'rgba(225,29,72,0.12)', high: isDark?'rgba(255,255,255,0.08)':'rgba(0,0,0,0.06)', medium: isDark?'rgba(255,255,255,0.05)':'rgba(0,0,0,0.04)'};
              tooltip.innerHTML = '<div class="tt-date">' + d.date + '</div><div class="tt-label" style="color:'+track.color+'">' + d.label + '</div><div class="tt-detail">' + d.detail + '</div><span class="tt-sig" style="background:'+sb[d.significance]+';color:'+sc[d.significance]+'">' + d.significance + '</span>';
              var rect = container.getBoundingClientRect();
              tooltip.style.left = (event.clientX - rect.left + 14) + 'px';
              tooltip.style.top = (event.clientY - rect.top - 10) + 'px';
              tooltip.classList.add('show');
            })
            .on('mouseleave', function() { tooltip.classList.remove('show'); });

          // Label
          g.append('text').attr('x', cx).attr('y', cy - d.r - 5)
            .attr('text-anchor', 'middle').attr('fill', labelColor)
            .attr('font-size', d.significance === 'critical' ? '10px' : '9px')
            .attr('font-family', 'Inter, sans-serif')
            .attr('font-weight', d.significance === 'critical' ? '600' : '400')
            .text(d.label.length > 20 ? d.label.substring(0, 19) + '…' : d.label);
        });
      });
    }

    // ===== BUILD INVESTMENT CHART =====
    function buildInvestmentChart() {
      if (typeof Chart === 'undefined' || !investmentData) return;
      var canvas = document.getElementById('investmentChart');
      if (!canvas) return;

      if (window.investChart) { try { window.investChart.destroy(); } catch(e) {} }

      var isDark = document.documentElement.classList.contains('theme-dark');
      var tc = isDark ? '#999' : '#64748b';
      var gc = isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.04)';
      var lc = isDark ? '#10b981' : '#059669';
      var fc = isDark ? 'rgba(16,185,129,0.15)' : 'rgba(5,150,105,0.12)';

      window.investChart = new Chart(canvas.getContext('2d'), {
        type: 'line',
        data: {
          labels: investmentData.map(function(d){return d.year;}),
          datasets: [{
            label: 'Global Private AI Investment ($B)',
            data: investmentData.map(function(d){return d.investment;}),
            borderColor: lc, backgroundColor: fc, fill: true,
            tension: 0.3, pointRadius: 4,
            pointBackgroundColor: lc,
            pointBorderColor: isDark ? '#141414' : '#FFFFFF',
            pointBorderWidth: 2, pointHoverRadius: 7, borderWidth: 2.5
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false, animation: false,
          plugins: {
            tooltip: { enabled: true, padding: 12, cornerRadius: 8,
              titleFont: {size:13, family:'Inter'}, bodyFont: {size:12, family:'Inter'},
              callbacks: { label: function(c){ return '$' + c.parsed.y + 'B'; } }
            },
            legend: { display: true, labels: { color: tc, font: {size:12, family:'Inter'}, boxWidth:12, boxHeight:12, borderRadius:3 } }
          },
          scales: {
            x: { ticks: {color:tc, font:{size:11, family:'Inter'}, maxRotation:0}, grid: {color:gc, drawBorder:false} },
            y: { ticks: {color:tc, font:{size:11, family:'Inter'}, callback: function(v){return '$'+v+'B';}}, grid: {color:gc, drawBorder:false}, beginAtZero:true }
          },
          layout: { padding: {top:10, right:20, bottom:10, left:10} }
        }
      });
    }

    // ===== THEME CHANGE =====
    function onThemeChange() {
      if (!dataReady) return;
      chartsBuilt = false;
      buildTimeline();
      buildInvestmentChart();
      chartsBuilt = true;
    }

    // ===== INIT =====
    window.addEventListener('load', function() {
      buildTimeline();
      buildInvestmentChart();
      chartsBuilt = true;
    });

    setTimeout(function() {
      document.querySelectorAll('.reveal').forEach(function(el) { el.classList.add('visible'); });
    }, 500);
  </script>
